scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_0_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //원래있던 0 지우기
    WebSquare.wUnit.addCommand("set", "scwin.setSimulateDelete_grid1()");
    WebSquare.wUnit.addCommand("pause", "500");
    //더블클릭 후
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'gridView1_cell_0_0')");
    WebSquare.wUnit.addCommand("pause", "500");
    //1234 입력
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    //엔터
    WebSquare.wUnit.addCommand("set", "scwin.setSimulateEnter_grid1()");
    WebSquare.wUnit.addCommand("pause", "500");
    //123-4 확인
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'gridView1_cell_0_0').children[0].innerText == '123-4'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //다시 클릭 후
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_0_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //지우기
    WebSquare.wUnit.addCommand("set", "scwin.setSimulateDelete_grid1()");
    WebSquare.wUnit.addCommand("pause", "500");
    //더블클릭 후
