    //지우기
    WebSquare.wUnit.addCommand("set", "scwin.setSimulateDelete_grid2()");
    WebSquare.wUnit.addCommand("pause", "500");
    //더블클릭 후
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'gridView2_cell_0_0')");
    WebSquare.wUnit.addCommand("pause", "500");
    //1234567890 입력
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate6()");
    WebSquare.wUnit.addCommand("pause", "500");
    //엔터
    WebSquare.wUnit.addCommand("set", "scwin.setSimulateEnter_grid2()");
    WebSquare.wUnit.addCommand("pause", "500");
    //123-456-7890 확인
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'gridView2_cell_0_0').children[0].innerText == '123-456-7890'", "true");
